// 博客日志数据（日志页 src/pages/changelog.astro 与日历页共用一份）。
// 原先这份数据写在 changelog.astro 内部，2026-11-09 抽到这里：日历要按日期读它，
// 继续留在页面文件里没法共享。每条记录的 date 是按 GitHub 提交历史回填的
// 首次出现日期（北京时间）；以后新增记录记得带上 date（格式 YYYY-MM-DD）。

export interface ChangelogChange {
	no: string;
	cat: string;
	text: string;
	date?: string;
	detail?: string;
}

export interface ChangelogVersion {
	version: string;
	date: string;
	no: string;
	tags: string[];
	summary: string;
	count: string;
	background?: string;
	changes: ChangelogChange[];
	updateTags?: string[];
}

